 "content": "from collections import Counter


def transform(grid):
    """Fill one-cell horizontal gaps between foreground marks with color 2."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foregrounds = set(counts) - {background}
    result = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] in foregrounds and row[c + 1] in foregrounds:
                result[r][c] = 2
    return result


if __name__ == "__main__":
    # Basic execution check on a sparse foreground row.
    assert transform([[9, 8, 9, 8, 9]]) == [[9, 8, 2, 8, 9]]
    print("transform check passed")
